```rust
use eframe::{egui, epi};
use notify::{RecommendedWatcher, RecursiveMode, Watcher, Event};
use rfd::FileDialog;
use std::path::PathBuf;
use std::thread;
use crossbeam_channel::{unbounded, Receiver};

struct AppState {
    input: Option<PathBuf>,
    output: Option<PathBuf>,
    done: Option<PathBuf>,
    logs: Vec<String>,
    watching: bool,
    rx: Option<Receiver<Event>>,
    watcher_thread: Option<thread::JoinHandle<()>>,
}

impl Default for AppState {
    fn default() -> Self {
        Self {
            input: None,
            output: None,
            done: None,
            logs: vec![],
            watching: false,
            rx: None,
            watcher_thread: None,
        }
    }
}

impl epi::App for AppState {
    fn name(&self) -> &str {
        "Rust Folder Monitor"
    }

    fn update(&mut self, ctx: &egui::Context, _frame: &epi::Frame) {
        egui::CentralPanel::default().show(ctx, |ui| {
            ui.heading("Folder Monitor");

            ui.horizontal(|ui| {
                if ui.button("Select Input").clicked() {
                    if let Some(path) = FileDialog::new().pick_folder() {
                        self.input = Some(path);
                    }
                }
                ui.label(self.input.as_ref().map(|p| p.display().to_string()).unwrap_or("None".to_string()));
            });

            ui.horizontal(|ui| {
                if ui.button("Select Output").clicked() {
                    if let Some(path) = FileDialog::new().pick_folder() {
                        self.output = Some(path);
                    }
                }
                ui.label(self.output.as_ref().map(|p| p.display().to_string()).unwrap_or("None".to_string()));
            });

            ui.horizontal(|ui| {
                if ui.button("Select Done").clicked() {
                    if let Some(path) = FileDialog::new().pick_folder() {
                        self.done = Some(path);
                    }
                }
                ui.label(self.done.as_ref().map(|p| p.display().to_string()).unwrap_or("None".to_string()));
            });

            if !self.watching {
                if ui.button("Start").clicked() {
                    if let Some(input_path) = &self.input {
                        let (tx, rx) = unbounded();
                        let path = input_path.clone();
                        let watcher_thread = thread::spawn(move || {
                            let mut watcher = RecommendedWatcher::new(
                                move |res| {
                                    if let Ok(event) = res {
                                        let _ = tx.send(event);
                                    }
                                },
                                notify::Config::default(),
                            ).expect("Failed to create watcher");
                            watcher.watch(&path, RecursiveMode::NonRecursive).expect("Failed to watch");
                            loop { std::thread::sleep(std::time::Duration::from_secs(60)); }
                        });
                        self.rx = Some(rx);
                        self.watcher_thread = Some(watcher_thread);
                        self.watching = true;
                        self.logs.push(format!("Started watching {}", input_path.display()));
                    } else {
                        self.logs.push("Please select input folder first.".to_string());
                    }
                }
            }

            ui.separator();
            ui.label("Events:");
            egui::ScrollArea::vertical().max_height(200.0).show(ui, |ui| {
                for log in &self.logs {
                    ui.label(log);
                }
            });
        });

        if let Some(rx) = &self.rx {
            while let Ok(event) = rx.try_recv() {
                let msg = format!("Event: {:?} on {:?}", event.kind, event.paths);
                self.logs.push(msg);
                ctx.request_repaint();
            }
        }
    }
}

fn main() {
    let app = AppState::default();
    let native_options = eframe::NativeOptions::default();
    eframe::run_native(Box::new(app), native_options);
}
```

