const updateUserPasswordSchema = z.object({
  password: z.string(),
  new_password: z.string(),
  new_password_confirmation: z.string(),
});

// bcrypt.compareをPromise化
function comparePassword(plain: string, hash: string): Promise<boolean> {
  return new Promise((resolve, reject) => {
    bcrypt.compare(plain, hash, (err, result) => {
      if (err) return reject(err);
      resolve(result);
    });
  });
}

// パスワードバリデーション
function validateNewPasswords(
  current: string,
  next: string,
  confirm: string
): string | null {
  if (current === next) {
    return "新しいパスワードは現在のパスワードと違うものを入力してください";
  }
  if (next !== confirm) {
    return "新しいパスワードが一致しません";
  }
  return null;
}

const updateUserPassword: FastifyPluginAsyncTypeProvider = async (fastify) => {
  fastify.setSerializerCompiler(serializerCompiler);
  fastify.setValidatorCompiler(validatorCompiler);

  fastify.patch(
    "/",
    {
      schema: { body: updateUserPasswordSchema },
    },
    async (request, reply) => {
      // 認証ユーザー取得
      const authedUser = validateAuthUser(request.user);

      // ユーザー情報取得
      const user = await prisma.users.findUnique({
        where: { id: authedUser.id },
      });
      if (!user) {
        throw fastify.httpErrors.notFound("ユーザー情報がありません");
      }

      // パスワード照合
      let isMatch: boolean;
      try {
        isMatch = await comparePassword(request.body.password, user.password);
      } catch {
        throw fastify.httpErrors.internalServerError();
      }
      if (!isMatch) {
        throw fastify.httpErrors.badRequest("現在のパスワードが異なります");
      }

      // 新パスワードバリデーション
      const error = validateNewPasswords(
        request.body.password,
        request.body.new_password,
        request.body.new_password_confirmation
      );
      if (error) {
        throw fastify.httpErrors.badRequest(error);
      }

      // パスワード更新
      await changePassword({
        user_id: authedUser.id,
        password: request.body.new_password,
      });

