public class DoctorAccount implements Account {
    @Id
    private Integer id;
    // ... other fields and getters/setters
}

@Entity
@Table(name = "user_account")
public class UserAccount implements Account {
    @Id
    private Integer id;
    // ... other fields and getters/setters
}
```

3. **Define a UserType enum:**
```java
public enum UserType {
    DOCTOR, USER
    // add more as needed
}
```

4. **Create a strategy interface:**
```java
public interface AccountRetrievalStrategy {
    Optional<? extends Account> findById(Integer id);
    boolean supports(UserType userType);
}
```

5. **Implement a strategy for each account type:**
```java
@Service
public class DoctorAccountRetrievalStrategy implements AccountRetrievalStrategy {
    private final DoctorAccountRepository repo;
    public DoctorAccountRetrievalStrategy(DoctorAccountRepository repo) { this.repo = repo; }
    @Override
    public Optional<DoctorAccount> findById(Integer id) { return repo.findById(id); }
    @Override
    public boolean supports(UserType userType) { return userType == UserType.DOCTOR; }
}

@Service
public class UserAccountRetrievalStrategy implements AccountRetrievalStrategy {
    private final UserAccountRepository repo;
    public UserAccountRetrievalStrategy(UserAccountRepository repo) { this.repo = repo; }
    @Override
    public Optional<UserAccount> findById(Integer id) { return repo.findById(id); }
    @Override
    public boolean supports(UserType userType) { return userType == UserType.USER; }
}
```

6. **Create a factory/registry to select the correct strategy:**
```java
@Component
public class AccountStrategyFactory {
    private final List<AccountRetrievalStrategy> strategies;
    public AccountStrategyFactory(List<AccountRetrievalStrategy> strategies) { this.strategies = strategies; }
    public AccountRetrievalStrategy getStrategy(UserType userType) {
        return strategies.stream()
            .filter(s -> s.supports(userType))
            .findFirst()
            .orElseThrow(() -> new IllegalArgumentException("No strategy for " + userType));
    }
}
```

7. **Service layer usage:**
```java
@Service
public class AccountService {
    private final AccountStrategyFactory factory;
    public AccountService(AccountStrategyFactory factory) { this.factory = factory; }
    public Optional<? extends Account> getAccountById(UserType userType, Integer id) {
        return factory.getStrategy(userType).findById(id);
    }
}
```

