Here is a sample implementation:

```cpp
#include <QCoreApplication>
#include <QDebug>
#include <QSet>
#include <QString>
#include <QVariant>
#include "xlsxdocument.h"

bool parseCellToInt(const QVariant &cellValue, int &result) {
    // If it's already a number
    if (cellValue.canConvert<double>()) {
        double d = cellValue.toDouble();
        int i = static_cast<int>(d);
        if (qFuzzyCompare(d, double(i))) {
            result = i;
            return true;
        }
    }
    // If it's a string, parse accordingly
    QString s = cellValue.toString().trimmed().toLower();
    if (s.isEmpty()) return false;

    bool ok = false;
    // Hexadecimal
    if (s.startsWith("0x")) {
        result = s.mid(2).toInt(&ok, 16);
        return ok;
    }
    // Binary
    if (s.startsWith("0b")) {
        result = s.mid(2).toInt(&ok, 2);
        return ok;
    }
    // Octal (classic C-style, e.g. 052)
    if (s.startsWith('0') && s.length() > 1 && s.indexOf(QRegExp("[^0-7]")) == -1) {
        result = s.toInt(&ok, 8);
        return ok;
    }
    // Decimal
    result = s.toInt(&ok, 10);
    if (ok) return true;
    // Try as double, but only accept if integer
    double d = s.toDouble(&ok);
    if (ok) {
        int i = static_cast<int>(d);
        if (qFuzzyCompare(d, double(i))) {
            result = i;
            return true;
        }
    }
    return false;
}

int main(int argc, char *argv[]) {
    QCoreApplication a(argc, argv);

    QString filePath = "example.xlsx";
    QString cellRef = "A1";

    QXlsx::Document xlsx(filePath);
    if (!xlsx.load()) {
        qWarning() << "Failed to load Excel file";
        return -1;
    }

    QVariant cellValue = xlsx.read(cellRef);
    if (!cellValue.isValid()) {
        qWarning() << "Cell is empty or invalid";
        return -1;
    }

    int value;
    if (!parseCellToInt(cellValue, value)) {
        qWarning() << "Could not parse cell value";
        return -1;
    }

    QSet<int> allowed = {0, 1, 2, 3, 10, 11, 42};
    if (allowed.contains(value)) {
        qDebug() << "Cell contains allowed value:" << value;
    } else {
        qDebug() << "Cell contains NOT allowed value:" << value;
    }

    return 0;
}
```

**Notes:**
