**My Answer:**

This is a classic minimum spanning tree (MST) problem with a twist: the cost to build a road between two houses is the sum of their prices, and some roads already exist. The goal is to connect all houses (make the graph connected) with the minimal total cost.

**Approach:**

1. **Find Connected Components:** Use Disjoint Set Union (DSU) to find all connected components based on the existing roads.
2. **Find the Cheapest House in Each Component:** For each component, find the house with the lowest price.
3. **Connect Components:** To minimize the cost, connect all components to the component containing the overall cheapest house. For each other component, connect its cheapest house to the overall cheapest house.
4. **Output:** The number of new roads is (number of components - 1), and the roads are between the overall cheapest house and the cheapest house in each other component.

**C++ Implementation:**

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent;
    DSU(int n) : parent(n+1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        parent[find(x)] = find(y);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<long long> a(n+1);
    for (int i = 1; i <= n; ++i) cin >> a[i];

    DSU dsu(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        dsu.unite(u, v);
    }

    // Find cheapest house in each component
    unordered_map<int, pair<long long, int>> comp_min;
    for (int i = 1; i <= n; ++i) {
        int root = dsu.find(i);
        if (comp_min.find(root) == comp_min.end() || a[i] < comp_min[root].first)
            comp_min[root] = {a[i], i};
    }

    // Find the overall cheapest house
    int min_house = -1;
    long long min_price = LLONG_MAX;
    for (auto& [root, p] : comp_min) {
        if (p.first < min_price) {
            min_price = p.first;
            min_house = p.second;
        }
    }

    // Connect all other components to the component with the overall cheapest house
    vector<pair<int, int>> roads;
    for (auto& [root, p] : comp_min) {
        if (p.second != min_house) {
            roads.emplace_back(min_house, p.second);
        }
    }

    cout << roads.size() << "\n";
    for (auto& [u, v] : roads) {
        cout << u << " " << v << "\n";
    }
    return 0;
}
```

**Explanation:**
- We use DSU to find components.
- For each component, we find its cheapest house.
- We connect all components to the one with the overall cheapest house, minimizing the total cost.

