Given n houses, each with a price, and m existing roads, we need to add the minimum-cost set of new roads so that the city becomes fully connected. The cost of a new road between house i and j is a[i] + a[j]. Output the number of new roads and their endpoints.

**Approach:**
1. Use Union-Find (DSU) to find the connected components after adding the m existing roads.
2. For each component, find the house with the minimum price.
3. To connect all components with minimal cost, connect the component with the overall minimum-priced house to the minimum-priced house in every other component.
4. Output the number of new roads (number of components - 1) and the list of roads.

**C++ Implementation:**
```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent;
    DSU(int n) : parent(n) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x != y) parent[y] = x;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    DSU dsu(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        dsu.unite(u, v);
    }

    // Find the minimum price house in each component
    unordered_map<int, pair<long long, int>> comp_min;
    for (int i = 0; i < n; ++i) {
        int root = dsu.find(i);
        if (comp_min.find(root) == comp_min.end() || a[i] < comp_min[root].first)
            comp_min[root] = {a[i], i};
    }

    // Find the global minimum
    int global_min_idx = -1;
    long long global_min_price = LLONG_MAX;
    for (auto& [root, p] : comp_min) {
        if (p.first < global_min_price) {
            global_min_price = p.first;
            global_min_idx = p.second;
        }
    }

    // Connect global_min_idx to each other component's min
    vector<pair<int, int>> roads;
    for (auto& [root, p] : comp_min) {
