const PostApiPanel = ({ apiPrefix }) => {
  const methods = [
    { name: "DetectObjects", endpoint: `/api/${apiPrefix}/detectObjects`, defaultBody: { imageUrl: "" } },
    { name: "ClassifyImage", endpoint: `/api/${apiPrefix}/classifyImage`, defaultBody: { imageUrl: "" } },
    { name: "FindPosition", endpoint: `/api/${apiPrefix}/findPosition`, defaultBody: { imageUrl: "", target: "" } },
    // Add more methods as needed
  ];
  const [selected, setSelected] = useState(null);
  const [postUri, setPostUri] = useState("");
  const [postBody, setPostBody] = useState("");
  const [responseJson, setResponseJson] = useState("");
  const [mockResponseJson, setMockResponseJson] = useState("");

  const selectMethod = (method) => {
    setSelected(method);
    setPostUri(method.endpoint);
    setPostBody(JSON.stringify(method.defaultBody, null, 2));
    setResponseJson("");
    setMockResponseJson("");
  };

  const sendPost = async () => {
    try {
      const res = await fetch(postUri, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: postBody,
      });
      const data = await res.json();
      const dataStr = JSON.stringify(data, null, 2);
      setResponseJson(dataStr);
      setMockResponseJson(dataStr);
    } catch (e) {
      setResponseJson("Error: " + e.message);
    }
  };

  const setMockResponse = async () => {
    if (!selected) return;
    try {
      const parsed = JSON.parse(mockResponseJson);
      const apiName = selected.name.charAt(0).toLowerCase() + selected.name.slice(1);
      await fetch(`/api/setresponse/${apiPrefix}/${apiName}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(parsed),
      });
      alert("Mock response set!");
    } catch (e) {
      alert("Invalid JSON in response field.");
    }
  };

