      <div class="panel-header">
        <h4 class="panel-title">POST API Methods</h4>
      </div>
      <div class="panel-body">
        <div class="btn-group btn-group-block">
          ${methods.map((m) => html`
            <button class="btn" onClick=${() => selectMethod(m)}>${m.name}</button>
          `)}
