          .replace(/\b(function|return|var|let|const|if|else|for|while|do|break|continue|switch|case|default|throw|try|catch|finally|new|typeof|instanceof|in|of|this|class|extends|super|import|from|export|await|async|yield)\b/g, '<span class="token keyword">$1</span>')
