#include <Wire.h>
#include <RTClib.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define OLED_RESET -1
Adafruit_SSD1306 display(128, 64, &Wire, OLED_RESET);
RTC_DS3231 rtc;

const int livingRoomTVPin = 2;
const int bedroomTVPin = 3;
const int nightModePin = 4; // Button

unsigned long simStartMillis;
unsigned long simulationStartTime = 6 * 3600; // 06:00:00
unsigned long SIM_FACTOR = 6;

void setup() {
  pinMode(livingRoomTVPin, OUTPUT);
  pinMode(bedroomTVPin, OUTPUT);
  pinMode(nightModePin, INPUT_PULLUP);
  Wire.begin();
  rtc.begin();
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.clearDisplay();
  simStartMillis = millis();
}

bool flicker() {
  return random(0, 100) < 80;
}

void loop() {
  unsigned long realElapsed = millis() - simStartMillis;
  unsigned long simElapsed = (realElapsed / 1000UL) * SIM_FACTOR;
  unsigned long simTime = (simulationStartTime + simElapsed) % 86400;

  bool nightMode = digitalRead(nightModePin) == HIGH;
  unsigned long nightDuration = nightMode ? 2 * 3600 : 1 * 3600;

  // Event logic
  const char* event = "None";
  digitalWrite(livingRoomTVPin, LOW);
  digitalWrite(bedroomTVPin, LOW);

  if (simTime >= 6*3600 && simTime < 7*3600) {
    event = "Morning News";
    digitalWrite(bedroomTVPin, flicker() ? HIGH : LOW);
  } else if (simTime >= 19*3600 && simTime < 20*3600) {
    event = "Evening TV";
    digitalWrite(livingRoomTVPin, flicker() ? HIGH : LOW);
  } else if (simTime >= 22*3600 && simTime < 22*3600 + nightDuration) {
    event = "Bedtime TV";
    digitalWrite(bedroomTVPin, flicker() ? HIGH : LOW);
  }

  // Display
  display.clearDisplay();
  display.setTextSize(2);
  display.setCursor(0,0);
  display.print("Time:");
  display.println(/* format simTime as HH:MM:SS */);
  display.setTextSize(1);
  display.print("Event:");
  display.println(event);
  display.display();

  delay(100);
}
```
