            { id: 'username', info: 'Enter a unique username.' },
            { id: 'email', info: 'Enter your email address.' },
            { id: 'password', info: 'Choose a strong password.' },
            { id: 'fullname', info: 'Enter your full name.' }
        ];
        let step = 0;
        const infoBox = document.getElementById('infoBox');
        const nextBtn = document.getElementById('nextBtn');
        const submitBtn = document.getElementById('submitBtn');
        function setStep(i) {
            steps.forEach((s, idx) => {
                const input = document.getElementById(s.id);
                input.disabled = idx !== i;
                input.classList.toggle('active', idx === i);
            });
            infoBox.textContent = steps[i].info;
            nextBtn.style.display = i < steps.length - 1 ? '' : 'none';
            submitBtn.style.display = i === steps.length - 1 ? '' : 'none';
