```js
import { defineStore } from 'pinia';
import axios from 'axios';

export const useTableStore = defineStore('table', {
  state: () => ({
    rows: [],
    loading: false,
    hasMore: true,
  }),
  actions: {
    async fetchRows(start, count) {
      if (this.loading || !this.hasMore) return;
      this.loading = true;
      try {
        const res = await axios.get('/api/rows', { params: { start, count } });
        const newRows = res.data.rows;
        if (newRows.length < count) this.hasMore = false;
        this.rows.push(...newRows);
      } catch (e) {
        console.error(e);
      } finally {
        this.loading = false;
      }
    },
    reset() {
      this.rows = [];
      this.hasMore = true;
      this.loading = false;
    }
  }
});
```

