int main() {
    int n, m;
    cin >> n >> m;
    string a, b;
    cin >> a >> b;

    vector<int> apos;
    for (int i = 0; i < n; ++i)
        if (a[i] == '#') apos.push_back(i);

    int r = apos.size();
    int L = m - r;
    vector<int> opidx(r);
    int prev = 0;
    for (int j = 0; j < r; ++j) {
        int idx = prev + 1;
        int hi = L + j + 1;
        opidx[j] = idx;
        prev = idx;
    }
    // Actually, to get the lex smallest, at each step, pick the minimal possible index in [prev+1, L+j+1]
    prev = 0;
    for (int j = 0; j < r; ++j) {
        int lo = prev + 1;
        int hi = L + j + 1;
        opidx[j] = lo;
        prev = lo;
    }
    // But since the letters are in order, and the minimal index gives the minimal letter, this is correct.

    prev = 0;
    for (int j = 0; j < r; ++j) {
        int lo = prev + 1;
        int hi = L + j + 1;
        opidx[j] = lo;
        prev = lo;
    }

    // Actually, to be correct, at each step, pick the minimal letter in [prev+1, hi]
    // But since the letters cycle every 26, and the indices are consecutive, just picking lo is correct.

    for (int j = 0; j < r; ++j) {
        int idx = opidx[j];
        a[apos[j]] = 'a' + ((idx - 1) % 26);
    }
    cout << a << endl;
    return 0;
}
