        if (n == 0) {
            System.out.println(path);
            count++;
            return;
        }
        if (n >= 1) {
            path.add(1);
            findWays(n - 1, path);
            path.remove(path.size() - 1);
        }
        if (n >= 2) {
            path.add(2);
            findWays(n - 2, path);
            path.remove(path.size() - 1);
        }
    }
}
```

