            if (i == 0) d[i] = x[1] - x[0];
            else if (i == n - 1) d[i] = x[n - 1] - x[n - 2];
            else d[i] = min(x[i] - x[i - 1], x[i + 1] - x[i]);
        }
        int L = -1e9, R = 1e9;
        for (int i = 0; i < n; ++i) {
            L = max(L, x[i] - d[i] + 1);
            R = min(R, x[i] + d[i] - 1);
