        unordered_set<int> s(x.begin(), x.end());
        bool found = false;
        for (int p = L; p <= R; ++p) {
            if (s.count(p) == 0) {
                found = true;
                break;
            }
        }
        cout << (found ? "YES" : "NO") << '\n';
    }
    return 0;
}
```

